import time
from onbellek import onbellekle

@onbellekle(ttl=1)
def test_func(x, y):
    return x + y

# Test 1: Temel çalışma ve TTL
assert test_func(1, 2) == 3
assert test_func(1, 2) == 3  # isabet olmalı
time.sleep(1.1)
assert test_func(1, 2) == 3  # ttl doldu, iska olmalı

# Test 2: İsimli argüman sırası (kwargs)
@onbellekle()
def sum_args(a, b):
    return a + b

assert sum_args(a=1, b=2) == 3
assert sum_args(b=2, a=1) == 3  # Aynı olmalı

# Test 3: Hashlenemeyen argümanlar (liste)
@onbellekle()
def list_func(l):
    return len(l)

assert list_func([1, 2]) == 2
assert list_func([1, 2]) == 2  # Doğrudan çalıştırılmalı ama hata vermemeli

print("Tüm gizli testler başarıyla geçti!")

